int h1, h2;
int a, b;

bool read() {
	return !!(cin >> h1 >> h2 >> a >> b);
}

void solve() {
	if (h1 + 8 * a >= h2)
		puts("0");
	else if (a > b) {
		int num = h2 - h1 - 8 * a, den = 12 * (a - b);
		cout << (num + den - 1) / den << endl;
	} else
		puts("-1");
}

const int N = 1010;

int n, a[N];

bool read() {
	if (!(cin >> n)) return false;
	forn(i, n) assert(scanf("%d", &a[i]) == 1);
	return true;
}

int ans[N];

void solve() {
	sort(a, a + n);

	int p = 0, q = n - 1;
	forn(i, n)
		if (i & 1) ans[i] = a[q--];
		else ans[i] = a[p++];
	assert(q + 1 == p);

	forn(i, n) {
		if (i) putchar(' ');
		printf("%d", ans[i]);
	}
	puts("");
}

