int pos[N];
vector<int> z[N];

void solve() {
	forn(i, n) pos[p[i]] = i;
	forn(i, n) z[i].clear();
	forn(i, m) {
		int x = pos[b[i].x], y = pos[b[i].y];
		if (x > y) swap(x, y);
		z[x].pb(y);
	}

	li ans = 0;
	int rg = n;
